181	func (d *EmailDispatcher) buildMemoMentionEmailMessage(message *storepb.InboxMessage, receiver *store.User, senderName string, memosByID map[int32]*store.Memo) (*email.Message, error) {
182		payload := message.GetMemoMention()
183		if payload == nil {
184			return nil, nil
185		}
186		memo := memosByID[payload.MemoId]
187		if !canViewerAccessMemo(receiver, memo) {
188			return nil, nil
189		}
190		url := d.memoURL(memo)
191		if url == "" {
192			return nil, nil
193		}
194	
195		body := []string{
196			fmt.Sprintf("Hi %s,", displayNameForEmail(receiver)),
197			"",
198			fmt.Sprintf("%s mentioned you in a memo.", senderName),
199			"",
200			"Open in Memos:",
201			url,
202			"",
203			"You are receiving this because you were mentioned in this memo.",
204		}
205	
206		return &email.Message{
207			To:      []string{receiver.Email},
208			Subject: fmt.Sprintf("[Memos] %s mentioned you in a memo", senderName),
209			Body:    strings.Join(body, "\n"),
210		}, nil
211	}
